new Promise((resolve) => {
  console.log(1);
  resolve(2);
}).then((n) => console.log(n));
console.log(3);

Promise.resolve(1)
  .then((n) => n + 2)
  .then((n) => console.log(n));

Promise.resolve()
  .then(() => {
    throw 1;
  })
  .catch(() => console.log(2))
  .then(() => console.log(3));

Promise.resolve(1)
  .finally(() => console.log(2))
  .then((n) => console.log(n));

Promise.reject(1)
  .finally(() => console.log(2))
  .catch((n) => console.log(n));

const p = Promise.resolve(1);
p.then((n) => console.log(n));
p.then((n) => console.log(n + 1));

Promise.resolve(1)
  .then((n) => {
    console.log(n);
  })
  .then((n) => console.log(n === undefined ? 0 : n));

async function f() {
  console.log(1);
  await Promise.resolve();
  console.log(2);
}
f();
console.log(3);

async function f() {
  return 4;
}
f().then((n) => console.log(n));
console.log(5);

async function f() {
  throw 1;
}
try {
  f().catch((n) => console.log(n));
  console.log(2);
} catch {
  console.log(3);
}

Promise.all([Promise.resolve(2), Promise.resolve(1)]).then(([a, b]) => {
  console.log(a);
  console.log(b);
});

Promise.all([
  Promise.resolve(1),
  Promise.reject(2),
  Promise.resolve(3),
]).then(
  () => console.log(0),
  (n) => console.log(n),
);

Promise.race([
  Promise.reject(1),
  Promise.resolve(2),
]).then(
  (n) => console.log(n),
  (n) => console.log(n),
);

new Promise((resolve) => {
  resolve(1);
  resolve(2);
}).then((n) => console.log(n));
